  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(iso == null ? '' : iso));
  if (!m) return null;
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  return Number(m[3]) + ' ' + months[Number(m[2]) - 1] + ' ' + m[1];
}

function trimOrder(o) {
  return {
    dates_display: {
      ordered: displayDate(o.order_date), shipped: displayDate(o.shipped_date), estimated_delivery: displayDate(o.estimated_delivery),
      delivered: displayDate(o.delivered_date), cancelled: displayDate(o.cancelled_date),
    },
    order_id: o.order_id,
    customer_first_name: String(o.customer_name || '').split(/\s+/)[0] || '',
    order_date: o.order_date,
    items: (o.items || []).map(function (i) { return { name: i.name, qty: i.qty, unit_price: i.unit_price }; }),
    subtotal: o.subtotal,
    shipping_fee: o.shipping_fee,
    cod_fee: o.cod_fee,
    total: o.total,
    payment_method: o.payment_method,
    status: o.status,
    courier: o.courier,
    tracking_url: o.tracking_url,
    shipped_date: o.shipped_date,
    estimated_delivery: o.estimated_delivery,
    delivered_date: o.delivered_date,
    cancelled_date: o.cancelled_date,
    cancellation_reason: o.cancellation_reason,
    refund_status: o.refund_status,
    shipping_address: o.shipping_address,
  };
}

// Values the reply must never contain when the sender is not the owner.
// Only returned when include_withheld is true (the workflow's own call).
// The agent's tool call never sets it, so the model cannot see these.
function withheldValues(o) {
  const a = o.shipping_address || {};
  const vals = [o.tracking_url, o.courier, a.line1, a.city, a.pincode, o.shipped_date, o.estimated_delivery, o.delivered_date];
  if (o.tracking_url) vals.push(String(o.tracking_url).split('/').pop());
  return vals.filter(function (v) { return v !== null && v !== undefined && String(v) !== ''; }).map(String);
}

function resolveOrder(input) {
  const orders = (input && input.orders) || [];
  const requester = String((input && input.requester_email) || '').trim().toLowerCase();
  const rawId = input && input.order_id ? String(input.order_id).trim().toUpperCase() : '';
  const allowEmail = !(input && input.allow_email_fallback === false);
  const includeWithheld = !!(input && input.include_withheld);

  const base = { found: false, authorized: false, match_method: 'none', order_id: rawId || null, order: null, reason: '' };

  if (rawId) {
    const hit = orders.filter(function (o) { return String(o.order_id).toUpperCase() === rawId; })[0];
    if (!hit) {
      // Never substitute another order for an ID the customer wrote.
      base.reason = 'No order exists with ID ' + rawId + '.';
      return base;
    }
    const owner = String(hit.customer_email || '').trim().toLowerCase();
    if (owner !== requester) {
      const out = { found: true, authorized: false, match_method: 'order_id', order_id: rawId, order: null, reason: 'The requester is not the customer on this order. Share and confirm no order detail.' };
      if (includeWithheld) out.withheld = withheldValues(hit);
      return out;
    }
    return { found: true, authorized: true, match_method: 'order_id', order_id: rawId, order: trimOrder(hit), reason: '' };
  }

  if (!allowEmail || !requester) {
    base.reason = 'No order ID was given.';
    return base;
  }

  const mine = orders.filter(function (o) { return String(o.customer_email || '').trim().toLowerCase() === requester; });
  if (mine.length === 1) {
    return { found: true, authorized: true, match_method: 'sender_email', order_id: mine[0].order_id, order: trimOrder(mine[0]), reason: '' };
  }
  if (mine.length > 1) {
    base.reason = 'Multiple orders exist for this email (' + mine.map(function (o) { return o.order_id; }).join(', ') + '). Ask which order.';
    return base;
  }
  base.reason = 'No order ID was given and no order exists for the sender email.';
  return base;
}

const email = $('Normalize Email').first().json;
const fin = $('Finalize Classification').first().json;
const raw = $('HTTP: Orders').first().json.data;
const orders = (typeof raw === 'string' ? JSON.parse(raw) : raw).orders;
const orderIntents = ['order_status', 'return_refund', 'complaint'];
let lookup = { found: false, authorized: false, match_method: 'none', order_id: null, order: null, reason: 'Lookup not needed for this intent.' };
if (fin.lookup_order_id || orderIntents.indexOf(fin.classification.intent) !== -1) {
  lookup = resolveOrder({ orders, order_id: fin.lookup_order_id, requester_email: email.from_email, allow_email_fallback: true, include_withheld: true });
}
return [{ json: lookup }];

// ---- from code/lib/compute_facts.js (unit-tested in code/test) ----
// "2026-11-20..." -> whole days since 1970 (UTC). Timezone-proof: only the date part is used.
function dayNumber(s) {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(s == null ? '' : s));
  if (!m) return null;
  return Math.floor(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])) / 86400000);
}

function computeFacts(input) {
  const email = (input && input.email) || {};
  const c = (input && input.classification) || {};
  const lookup = (input && input.lookup) || {};
  const cfg = (input && input.config) || {};
  const returnWindow = typeof cfg.RETURN_WINDOW_DAYS === 'number' ? cfg.RETURN_WINDOW_DAYS : 7;
  const damageWindow = typeof cfg.DAMAGE_WINDOW_DAYS === 'number' ? cfg.DAMAGE_WINDOW_DAYS : 2;

  const order = lookup.found && lookup.authorized && lookup.order ? lookup.order : null;
  const attachments = Array.isArray(email.attachments) ? email.attachments : [];

  const facts = {
    has_order: !!order,
    order_status: order ? order.status : null,
    payment_method: order ? order.payment_method : null,
    delivered: !!(order && order.delivered_date),
    days_since_delivery: null,
    order_cancelled: !!(order && order.status === 'cancelled'),
    has_attachments: attachments.length > 0,
    attachment_count: attachments.length,
    product_condition: c.product_condition || 'unknown',
    issue_type: c.issue_type || 'none',
    return_eligibility: 'NO_ORDER',
    return_reason: '',
    refundable_amount: null,
    damage_window_ok: null,
  };

  if (!order) return facts;

  if (order.delivered_date) {
    const received = dayNumber(email.received_at);
    const delivered = dayNumber(order.delivered_date);
    if (received !== null && delivered !== null) facts.days_since_delivery = received - delivered;
  }

  // Return eligibility (FAQ section 4): within 7 days of delivery AND unused/unopened.
  if (!order.delivered_date || facts.days_since_delivery === null) {
    facts.return_eligibility = 'NOT_DELIVERED';
    facts.return_reason = 'The order has not been delivered, so the returns policy does not apply yet.';
  } else {
    const late = facts.days_since_delivery > returnWindow;
    const used = facts.product_condition === 'opened_or_used';
    if (late && used) {
      facts.return_eligibility = 'INELIGIBLE_BOTH';
      facts.return_reason = facts.days_since_delivery + ' days since delivery (limit ' + returnWindow + ') and the product has been opened or used.';
    } else if (late) {
      facts.return_eligibility = 'INELIGIBLE_WINDOW';
      facts.return_reason = facts.days_since_delivery + ' days since delivery (limit ' + returnWindow + ').';
    } else if (used) {
      facts.return_eligibility = 'INELIGIBLE_USED';
      facts.return_reason = 'The product has been opened or used; only unused, unopened, sealed items can be returned.';
    } else if (facts.product_condition === 'unknown') {
      facts.return_eligibility = 'UNKNOWN_CONDITION';
      facts.return_reason = 'Within ' + returnWindow + ' days, but the email does not say whether the product is unopened.';
    } else {
      facts.return_eligibility = 'ELIGIBLE';
      facts.return_reason = facts.days_since_delivery + ' days since delivery and the product is unopened.';
      // FAQ section 6: shipping and COD fees are non-refundable on ordinary returns.
      facts.refundable_amount = order.subtotal;
    }
    // FAQ section 5 says "within 48 hours of delivery". delivered_date has no time,
    // so 2 calendar days stands in for 48 hours (stated in the README).
    facts.damage_window_ok = facts.days_since_delivery <= damageWindow;
  }

  return facts;
}

return [{ json: computeFacts({ email: $('Normalize Email').first().json, classification: $('Finalize Classification').first().json.classification,
  lookup: $('Resolve Order').first().json, config: $('Config').first().json }) }];

// ---- from code/lib/decide_route.js (unit-tested in code/test) ----
const DR_MEDICAL = /\b(eczema|psoriasis|dermatitis|rosacea|allerg(y|ic|ies)|rash(es)?|infection|pregnan(t|cy)|skin (disease|condition)|medical|cure[sd]?|itch(y|ing)?|swelling|swollen|burning)\b/i;
const DR_INSTRUCTIONS = /(ignore (all |any )?(the )?(previous|prior|above) (instructions|rules)|system (note|prompt|message)|\bAI assistant\b|as an ai\b|disregard (the |all )?(polic(y|ies)|rules|instructions))/i;

function decideRoute(input) {
  const c = (input && input.classification) || {};
  const lookup = (input && input.lookup) || {};
  const facts = (input && input.facts) || {};
  const cfg = (input && input.config) || {};
  const email = (input && input.email) || {};
  const threshold = typeof cfg.CONFIDENCE_THRESHOLD === 'number' ? cfg.CONFIDENCE_THRESHOLD : 0.75;

  const llmIntent = c.intent || 'other';
  const text = String(email.text || '');
  const flags = (Array.isArray(c.risk_flags) ? c.risk_flags : []).slice();

  // Deterministic backstops (added in v2 after v1 missed these). They do not rely on the model.
  // 1. Medical or skin-reaction words: FAQ section 8 says a human must handle these.
  if (DR_MEDICAL.test(text) && flags.indexOf('medical') === -1) flags.push('medical');
  // 2. Text that addresses an AI or tries to override rules is flagged; it never changes routing.
  if (DR_INSTRUCTIONS.test(text) && flags.indexOf('embedded_instructions') === -1) flags.push('embedded_instructions');
  // 3. A damaged, leaking, wrong or missing item is a complaint (High priority, human verifies)
  //    even when the model filed it under return_refund because the customer asked for money back.
  const itemProblem = ['damaged', 'leaking', 'wrong_item', 'missing_item'].indexOf(c.issue_type) !== -1;
  const intent = (llmIntent === 'return_refund' && itemProblem) ? 'complaint' : llmIntent;
  const reroutedAsComplaint = intent !== llmIntent;

  const orderIntents = ['order_status', 'return_refund', 'complaint'];
  const isOrderIntent = orderIntents.indexOf(intent) !== -1;
  const privacyBlock = !!(lookup.found && lookup.authorized === false);
  const reasons = [];

  if (c.fallback_used) reasons.push('classification_fallback');
  if (typeof c.confidence !== 'number' || c.confidence < threshold) reasons.push('low_confidence');
  if (isOrderIntent && !lookup.found) reasons.push('order_not_found');
  if (privacyBlock) reasons.push('sender_not_owner');
  if (c.sentiment === 'angry') reasons.push('angry_customer');
  if (flags.indexOf('medical') !== -1) reasons.push('medical');
  if (flags.indexOf('threat_public') !== -1) reasons.push('public_threat');
  if (flags.indexOf('embedded_instructions') !== -1) reasons.push('embedded_instructions');
  if (intent === 'return_refund' && facts.has_order && facts.return_eligibility !== 'ELIGIBLE') reasons.push('refund_declined');
  if (intent === 'complaint') reasons.push('complaint_needs_verification');
  if (intent === 'order_status' && facts.order_cancelled) reasons.push('order_cancelled');
  if (intent === 'other' && (c.other_category === 'business_request' || c.other_category === 'unclear')) reasons.push('out_of_scope_request');

  const ticketNeeded = intent === 'return_refund' || intent === 'complaint';
  // Priority is fixed by intent (README: complaints are High). Never taken from the email.
  const priority = intent === 'complaint' ? 'High' : (intent === 'return_refund' ? 'Medium' : null);

  const languageNames = { en: 'English', hi: 'Hindi (Devanagari script)', hinglish: 'Hinglish (Hindi written in Latin script, mixed with English)' };

  // What the agent is told. Verdicts only: no order fields, no policy text.
  // It must call get_order / search_faq to get anything it wants to state.
  const brief = [];
  brief.push('intent: ' + intent + (c.secondary_intent ? ' (also: ' + c.secondary_intent + ')' : ''));
  brief.push('reply_language: ' + (languageNames[c.language] || 'English'));
  brief.push('customer_first_name: ' + (email.from_first_name || 'unknown'));
  if (privacyBlock) {
    brief.push('order_lookup: NOT_AUTHORISED. The sender is not the customer on this order. Do not share or confirm any order detail (status, dates, tracking, address, items, amounts). Ask that the customer who placed the order writes from the email address used for the order.');
  } else if (lookup.found) {
    brief.push('order_lookup: FOUND for order ' + lookup.order_id + (lookup.match_method === 'sender_email' ? ' (matched by the sender email; the customer gave no order ID)' : '') + '. Call get_order with this ID for the details.');
    if (facts.order_cancelled) brief.push('order_state: CANCELLED. The customer may not know. Explain using only what get_order returns.');
    if (facts.days_since_delivery !== null && facts.days_since_delivery !== undefined) brief.push('days_since_delivery: ' + facts.days_since_delivery);
  } else if (isOrderIntent) {
    brief.push('order_lookup: NOT_FOUND. ' + (lookup.reason || '') + ' Do not state any order status. Ask the customer to check the order ID and the email address used for the order.');
  } else {
    brief.push('order_lookup: NOT_APPLICABLE');
  }
  if (intent === 'return_refund' && facts.has_order) {
    brief.push('return_eligibility: ' + facts.return_eligibility + '. ' + (facts.return_reason || '') + ' This verdict is final.');
    if (facts.return_eligibility === 'ELIGIBLE' && facts.refundable_amount !== null) {
      brief.push('refundable_amount_inr: ' + facts.refundable_amount + ' (item value; shipping and COD fees are not refundable on ordinary returns). Payment method: ' + facts.payment_method + '.');
    } else {
      brief.push('Do not promise or approve a refund. Explain the policy kindly and say a team member will review.');
    }
  }
  if (intent === 'complaint') {
    brief.push('issue_type: ' + (facts.issue_type || 'none'));
    brief.push('photos_attached: ' + (facts.has_attachments ? 'yes (' + facts.attachment_count + ')' : 'no'));
    if (facts.damage_window_ok !== null && facts.damage_window_ok !== undefined) brief.push('reported_within_policy_window: ' + (facts.damage_window_ok ? 'yes' : 'no'));
    brief.push('A team member must verify before any refund or replacement. Do not say either is approved.');
  }
  if (flags.indexOf('medical') !== -1) brief.push('The email raises a medical or skin-condition question. Give no medical advice and make no cure or treatment claim.');

  return {
    route: intent,
    llm_intent: llmIntent,
    rerouted_as_complaint: reroutedAsComplaint,
    risk_flags: flags,
    draft_needed: intent !== 'other',
    ticket_needed: ticketNeeded,
    priority: priority,
    needs_human: reasons.length > 0,
    needs_human_reasons: reasons,
    privacy_block: privacyBlock,
    agent_brief: brief.join('\n'),
  };
}

return [{ json: decideRoute({ email: $('Normalize Email').first().json, classification: $('Finalize Classification').first().json.classification,
  lookup: $('Resolve Order').first().json, facts: $('Compute Facts').first().json, config: $('Config').first().json }) }];

// ---- from code/lib/postcheck_reply.js (unit-tested in code/test) ----
const PC_SIGNOFF = 'Warm regards,\nTeam Kesar';
const PC_CAPS_ALLOW = ['COD', 'UPI', 'IFSC', 'FAQ', 'INR', 'OTP', 'PIN', 'CVV', 'GST', 'KC'];

function holdingReply(firstName) {
  return 'Hi ' + (firstName || 'there') + ',\n\nThank you for writing to us. A member of our team is looking into this and will follow up within 24 business hours.\n\n' + PC_SIGNOFF;
}

// Agent output format: line 1 "STATUS: OK" or "STATUS: ESCALATE - <reason>",
// line 2 "FAQ: <section numbers or NONE>", then the reply.
function parseAgentOutput(text) {
  const raw = String(text == null ? '' : text).replace(/\r/g, '').trim();
  const lines = raw.split('\n');
  const statusMatch = /^\s*STATUS:\s*(OK|ESCALATE)\b\s*(?:[-:]\s*(.*))?$/i.exec(lines[0] || '');
  if (!statusMatch) {
    return { status: 'OK', escalate: false, escalate_reason: '', faq_sections: [], reply: raw, format_error: true };
  }
  let idx = 1;
  let faq = [];
  const faqMatch = /^\s*FAQ:\s*(.*)$/i.exec(lines[idx] || '');
  if (faqMatch) {
    faq = (faqMatch[1].match(/\d+/g) || []).map(Number);
    idx += 1;
  }
  const escalate = statusMatch[1].toUpperCase() === 'ESCALATE';
  return {
    status: escalate ? 'ESCALATE' : 'OK',
    escalate: escalate,
    escalate_reason: (statusMatch[2] || '').trim(),
    faq_sections: faq,
    reply: lines.slice(idx).join('\n').trim(),
    format_error: false,
  };
}

function pcAmounts(text) {
  const out = [];
  const re = /(?:₹|Rs\.?|INR)\s?([\d,]+(?:\.\d+)?)/gi;
  let m;
  while ((m = re.exec(String(text || ''))) !== null) {
    const n = Number(m[1].replace(/,/g, ''));
    if (!isNaN(n)) out.push(n);
  }
  return out;
}

function pcDateForms(iso) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(iso || ''));
  if (!m) return [];
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const d = String(Number(m[3]));
  const mon = months[Number(m[2]) - 1];
  return [iso, d + ' ' + mon, mon + ' ' + d, d + 'th ' + mon, d + 'st ' + mon, d + 'nd ' + mon, d + 'rd ' + mon];
}

function postcheckReply(input) {
  const lookup = (input && input.lookup) || {};
  const facts = (input && input.facts) || {};
  const route = (input && input.route) || {};
  const firstName = (input && input.first_name) || '';
  const toolsCalled = (input && input.tools_called) || [];
  let draft = String((input && input.draft) || '').trim();
  const soft0 = [];
  // Replies are plain-text emails: remove markdown emphasis the model sometimes adds.
  const noMarkdown = draft.replace(/\*\*([^*\n]+)\*\*/g, '$1').replace(/__([^_\n]+)__/g, '$1').replace(/`([^`\n]+)`/g, '$1').replace(/^#{1,6}\s+/gm, '');
  if (noMarkdown !== draft) { draft = noMarkdown; soft0.push('markdown_stripped'); }
  const lower = draft.toLowerCase();
  const order = lookup.found && lookup.authorized && lookup.order ? lookup.order : null;
  const critical = [];
  const soft = soft0;

  // 1. privacy_leak: sender is not the owner, yet the draft contains order details.
  if (route.privacy_block) {
    const withheld = Array.isArray(lookup.withheld) ? lookup.withheld : [];
    let leaked = /track\.example\.com/i.test(draft);
    for (let i = 0; i < withheld.length && !leaked; i++) {
      const forms = /^\d{4}-\d{2}-\d{2}$/.test(withheld[i]) ? pcDateForms(withheld[i]) : [withheld[i]];
      for (let j = 0; j < forms.length; j++) {
        if (forms[j] && lower.indexOf(String(forms[j]).toLowerCase()) !== -1) { leaked = true; break; }
      }
    }
    if (leaked) critical.push('privacy_leak');
  }

  // 2. invented_url: only the authorised order's tracking link or our own domain may appear.
  const urls = draft.match(/(?:https?:\/\/|www\.|track\.example\.com)[^\s)>\]"']*/gi) || [];
  const allowedTracking = order && order.tracking_url ? String(order.tracking_url).replace(/^https?:\/\//i, '').toLowerCase() : null;
  for (let i = 0; i < urls.length; i++) {
    const u = urls[i].replace(/[.,;:!?]+$/, '').replace(/^https?:\/\//i, '').replace(/^www\./i, '').toLowerCase();
    const host = u.split('/')[0];
    const ok = (allowedTracking && u === allowedTracking) || /(^|\.)kesarandco\.example$/.test(host);
    if (!ok) { critical.push('invented_url'); break; }
  }

  // 3. unbacked_amount: every rupee amount must exist in the order or the FAQ.
  const allowed = pcAmounts(input && input.faqText);
  if (order) {
    [order.subtotal, order.shipping_fee, order.cod_fee, order.total].forEach(function (n) { if (typeof n === 'number') allowed.push(n); });
    (order.items || []).forEach(function (it) { if (typeof it.unit_price === 'number') { allowed.push(it.unit_price); allowed.push(it.unit_price * (it.qty || 1)); } });
    pcAmounts(order.refund_status).forEach(function (n) { allowed.push(n); });
  }
  if (typeof facts.refundable_amount === 'number') allowed.push(facts.refundable_amount);
  const stated = pcAmounts(draft);
  for (let i = 0; i < stated.length; i++) {
    if (allowed.indexOf(stated[i]) === -1) { critical.push('unbacked_amount'); break; }
  }

  // 3b. unbacked_measure: a product size such as "100 ml" must exist in the order or the FAQ
  //     (added after a v2 draft invented a size for an item the customer had only named).
  const known = (String((input && input.faqText) || '') + ' ' + (order ? (order.items || []).map(function (it) { return it.name; }).join(' ') : '')).toLowerCase().replace(/\s+/g, '');
  const measures = draft.match(/\b\d+(?:\.\d+)?\s?(?:ml|g|gm|kg|l)\b/gi) || [];
  for (let i = 0; i < measures.length; i++) {
    if (known.indexOf(measures[i].toLowerCase().replace(/\s+/g, '')) === -1) { critical.push('unbacked_measure'); break; }
  }

  // 4. medical_claim: cure/treat words without a negation in the same sentence.
  const sentences = draft.split(/[.!?\n।]+/);
  for (let i = 0; i < sentences.length; i++) {
    const s = sentences[i];
    if (/\b(cure[sd]?|curing|heal(s|ed|ing)?|treat(s|ed|ing|ment)?|remed(y|ies))\b/i.test(s) &&
        !/\b(not|cannot|can't|can not|won't|don't|doesn't|isn't|aren't|never|no|unable|neither|nor)\b/i.test(s)) {
      critical.push('medical_claim');
      break;
    }
  }

  // 5. refund_promise: completed-state claims about a refund or replacement.
  const promise = /\b(refund|replacement)\b[^.!?\n]{0,60}\b(has been|have been|is|was|are)\s+(now\s+)?(approved|processed|credited|initiated|issued|confirmed)\b/i.test(draft) ||
                  /\b(approved|processed|initiated|issued|confirmed)\s+(your|the|a)\s+(full\s+)?(refund|replacement)\b/i.test(draft);
  const backedByOrder = !!(order && order.refund_status);
  const ineligible = typeof facts.return_eligibility === 'string' && facts.return_eligibility.indexOf('INELIGIBLE') === 0;
  if ((promise && !backedByOrder) || (ineligible && /\bapproved\b/i.test(draft))) critical.push('refund_promise');

  // Soft checks (noted, never block).
  if (draft.replace(/\s+/g, ' ').indexOf(PC_SIGNOFF.replace(/\s+/g, ' ')) === -1) {
    draft = draft.replace(/\s+$/, '') + '\n\n' + PC_SIGNOFF;
    soft.push('signoff_appended');
  }
  if (/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}]/u.test(draft)) soft.push('emoji');
  const caps = (draft.match(/\b[A-Z]{4,}\b/g) || []).filter(function (w) { return PC_CAPS_ALLOW.indexOf(w) === -1; });
  if (caps.length > 0) soft.push('all_caps');
  if ((draft.match(/!/g) || []).length > 1) soft.push('exclamations');
  const body = draft.replace(PC_SIGNOFF, '');
  if (body.split(/[.!?।]+\s/).filter(function (x) { return x.trim().length > 0; }).length > 8) soft.push('long_reply');
  if (route.route === 'order_status' && order && toolsCalled.indexOf('get_order') === -1) soft.push('no_get_order_call');

  if (critical.length > 0) {
    return { reply_draft: holdingReply(firstName), critical: critical, soft: soft, replaced: true };
  }
  return { reply_draft: draft, critical: critical, soft: soft, replaced: false };
}

// Parse the agent's output and run the safety checks. A failed critical check
// replaces the draft with a neutral holding reply and flags the email for a human.
const email = $('Normalize Email').first().json;
const route = $('Decide Route').first().json;
const lookup = $('Resolve Order').first().json;
const facts = $('Compute Facts').first().json;
let out = { reply_draft: '', critical: [], soft: [], replaced: false, escalate: false, escalate_reason: '', faq_sections: [], tools_called: [], tool_calls: 0, agent_error: '', format_error: false, agent_chars: 0 };
if (route.draft_needed) {
  let a = null;
  try { a = $('AI Agent: Draft Reply').first().json; } catch (e) { out.agent_error = String(e.message || e).slice(0, 300); }
  if (a && a.error) out.agent_error = String(a.error.message || a.error.description || JSON.stringify(a.error)).slice(0, 300);
  if (a && typeof a.output === 'string' && a.output.trim()) {
    const parsed = parseAgentOutput(a.output);
    const steps = Array.isArray(a.intermediateSteps) ? a.intermediateSteps : [];
    const tools = steps.map(function (s) { return s && s.action && s.action.tool; }).filter(Boolean);
    const pc = postcheckReply({ draft: parsed.reply, lookup, facts, route, faqText: String($('HTTP: FAQ').first().json.data || ''), first_name: email.from_first_name, tools_called: tools });
    out = Object.assign(out, pc, { escalate: parsed.escalate, escalate_reason: parsed.escalate_reason, faq_sections: parsed.faq_sections,
      tools_called: tools.filter(function (t, i) { return tools.indexOf(t) === i; }), tool_calls: tools.length, format_error: parsed.format_error, agent_chars: a.output.length });
  } else {
    out.agent_error = out.agent_error || 'agent returned no output';
    out.reply_draft = holdingReply(email.from_first_name);
    out.replaced = true;
  }
}
return [{ json: out }];

// ---- from code/lib/ticket_upsert.js (unit-tested in code/test) ----
function ticketDecision(input) {
  const rows = (input && input.rows) || [];
  const email = (input && input.email) || {};
  const c = (input && input.classification) || {};
  const lookup = (input && input.lookup) || {};
  const route = (input && input.route) || {};
  const now = (input && input.now) || '';

  if (!route.ticket_needed) return { action: 'none', row: null };

  const orderId = lookup.order_id || c.order_id || '';
  const customerEmail = email.from_email || '';
  const attachments = Array.isArray(email.attachments) ? email.attachments.length : 0;
  const noteLine = '[' + (email.received_at || '') + '] ' + (email.email_id || '') + ': ' + (c.summary || '') +
    (attachments > 0 ? ' (attachments: ' + attachments + ')' : '');

  const open = rows.filter(function (r) {
    if (String(r.status || '').trim().toLowerCase() === 'closed') return false;
    if (orderId) return String(r.order_id || '').trim().toUpperCase() === String(orderId).toUpperCase();
    // No order ID: fall back to the same customer and the same kind of issue.
    return !String(r.order_id || '').trim() && String(r.customer_email || '').trim().toLowerCase() === customerEmail && String(r.intent || '') === String(route.route || c.intent || '');
  });

  if (open.length > 0) {
    const t = Object.assign({}, open[0]);
    const ids = String(t.email_ids || '').split(',').map(function (s) { return s.trim(); }).filter(Boolean);
    if (ids.indexOf(email.email_id) !== -1) return { action: 'unchanged', row: t }; // re-sent email: idempotent
    ids.push(email.email_id);
    t.email_ids = ids.join(', ');
    t.notes = (String(t.notes || '').trim() ? String(t.notes).trim() + '\n' : '') + noteLine;
    t.updated_at = now;
    if (route.priority === 'High') t.priority = 'High'; // priority can rise, never fall
    return { action: 'update', row: t };
  }

  // The ticket ID is derived from the order (TKT-1052), not from a counter. Two emails about
  // different orders can then never be given the same ID, even if they are processed at the
  // same moment (a counter read from the Sheet collided in a test run when two runs overlapped).
  const base = orderId ? 'TKT-' + String(orderId).toUpperCase().replace(/^KC-/, '') : 'TKT-' + String(email.email_id || 'X');
  const taken = rows.map(function (r) { return String(r.ticket_id || '').trim(); });
  let ticketId = base;
  for (let n = 2; taken.indexOf(ticketId) !== -1; n++) ticketId = base + '-' + n; // a closed ticket already used this ID

  return {
    action: 'create',
    row: {
      ticket_id: ticketId,
      created_at: now,
      updated_at: now,
      order_id: orderId,
      customer_email: customerEmail,
      email_ids: email.email_id || '',
      intent: route.route || c.intent || '',
      priority: route.priority || 'Medium',
      status: 'Open',
      summary: c.summary || '',
      notes: noteLine,
    },
  };
}

// Existing ticket rows come from the Sheet; decide create / update / unchanged.
const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r && r.ticket_id; });
const readError = $input.first() && $input.first().json && $input.first().json.error ? String($input.first().json.error.message || $input.first().json.error) : '';
const d = ticketDecision({ rows, email: $('Normalize Email').first().json, classification: $('Finalize Classification').first().json.classification,
  lookup: $('Resolve Order').first().json, route: $('Decide Route').first().json, now: new Date().toISOString() });
return [{ json: { action: readError ? 'error' : d.action, ticket_id: d.row ? d.row.ticket_id : '', row: d.row, write: !readError && (d.action === 'create' || d.action === 'update'), error: readError } }];

// ---- from code/lib/audit_row.js (unit-tested in code/test) ----
function buildAuditRow(ctx) {
  const x = ctx || {};
  const email = x.email || {};
  const c = x.classification || {};
  const lookup = x.lookup || {};
  const route = x.route || {};
  const yesNo = function (v) { return v ? 'TRUE' : 'FALSE'; };
  const version = x.prompt_version || '';

  // The resolved order, or the ID the customer wrote even if it does not exist (e.g. KC-1099).
  const orderId = lookup.order_id || c.order_id || '';

  return {
    email_id: email.email_id || '',
    received_at: email.received_at || '',
    from_email: email.from_email || '',
    intent: c.intent || '',
    secondary_intent: c.secondary_intent || '',
    order_id: orderId,
    language: c.language || '',
    sentiment: c.sentiment || '',
    confidence: typeof c.confidence === 'number' ? c.confidence : '',
    order_found: yesNo(lookup.found),
    action_taken: x.action_taken || '',
    needs_human: yesNo(x.needs_human),
    ticket_id: x.ticket_id || '',
    reply_draft: x.reply_draft || '',
    prompt_version: version,
    processed_at: x.processed_at || '',
    error: x.error || '',
    notes: Array.isArray(x.notes) ? x.notes.join('; ') : (x.notes || ''),
    audit_key: (email.email_id || '') + '|' + version,
    json_valid_first_try: yesNo(x.json_valid_first_try),
    needs_human_reasons: Array.isArray(x.needs_human_reasons) ? x.needs_human_reasons.join('; ') : (x.needs_human_reasons || ''),
    tokens_est: typeof x.tokens_est === 'number' ? x.tokens_est : '',
    cost_usd_est: typeof x.cost_usd_est === 'number' ? x.cost_usd_est : '',
  };
}

const email = $('Normalize Email').first().json;
const cfg = $('Config').first().json;
const fin = $('Finalize Classification').first().json;
const lookup = $('Resolve Order').first().json;
const route = $('Decide Route').first().json;
const pc = $('Postcheck Reply').first().json;
let td = null; try { td = $('Ticket Decision').first().json; } catch (e) { td = null; }
let ticketWriteError = '';
try { const w = $('Sheets: Upsert Ticket').first().json; if (w && w.error) ticketWriteError = String(w.error.message || w.error); } catch (e) {}

const reasons = (route.needs_human_reasons || []).slice();
(pc.critical || []).forEach(function (c) { reasons.push('postcheck:' + c); });
if (pc.escalate) reasons.push('faq_gap');
if (pc.agent_error) reasons.push('agent_error');
if (fin.llm_error && fin.repair_method === 'fallback') reasons.push('classifier_error');
const ticketError = (td && td.error) || ticketWriteError;
if (ticketError) reasons.push('ticket_error');

const errors = [];
if (fin.llm_error) errors.push('classify: ' + fin.llm_error);
if (pc.agent_error) errors.push('agent: ' + pc.agent_error);
if (ticketError) errors.push('ticket: ' + ticketError);

let action = 'log_only';
if (route.draft_needed) {
  action = pc.agent_error ? 'error_fallback' : 'draft_reply';
  if (td && td.action === 'create') action += '+ticket_created';
  if (td && (td.action === 'update' || td.action === 'unchanged')) action += '+ticket_updated';
}

const notes = ['order_match=' + (lookup.match_method || 'none'), 'order_id_source=' + fin.order_id_source, 'repair=' + fin.repair_method];
if ((fin.notes || []).length) notes.push('classify_notes=' + fin.notes.join(','));
if (route.draft_needed) notes.push('tools=' + ((pc.tools_called || []).join(',') || 'none'), 'faq=' + ((pc.faq_sections || []).join(',') || 'none'));
if ((pc.soft || []).length) notes.push('voice=' + pc.soft.join(','));
if (pc.replaced) notes.push('draft_replaced_by_holding_reply');
if (pc.escalate_reason) notes.push('agent_escalated=' + pc.escalate_reason);
if (lookup.reason) notes.push('lookup=' + lookup.reason);
if (fin.classification.intent === 'other' && fin.classification.other_category === 'partnership') notes.push('partnership enquiry; FAQ section 9 contact partnerships@kesarandco.example');
if (td && td.action) notes.push('ticket=' + td.action);
if (route.rerouted_as_complaint) notes.push('routed_as=complaint (item problem reported; model intent was ' + route.llm_intent + ')');

// Token and cost ESTIMATE (characters / 4). Labelled as an estimate everywhere it is reported.
const classifyIn = (3602 + email.email_block.length) / 4;
const classifyOut = (fin.classify_raw_chars || 0) / 4;
let agentIn = 0, agentOut = 0;
if (route.draft_needed && !pc.agent_error) {
  const turns = 1 + (pc.tool_calls || 0);
  const base = (3526 + route.agent_brief.length + email.email_block.length) / 4 + 250;
  agentIn = base * turns + 350 * (pc.tool_calls || 0) * (turns / 2);
  agentOut = (pc.agent_chars || 0) / 4 + 40 * (pc.tool_calls || 0);
}
const tokensIn = Math.round(classifyIn + agentIn), tokensOut = Math.round(classifyOut + agentOut);
const cost = (classifyIn * cfg.PRICE_CLASSIFY_IN_USD_PER_M + classifyOut * cfg.PRICE_CLASSIFY_OUT_USD_PER_M + agentIn * cfg.PRICE_AGENT_IN_USD_PER_M + agentOut * cfg.PRICE_AGENT_OUT_USD_PER_M) / 1e6;

const row = buildAuditRow({ email, classification: fin.classification, lookup, route, prompt_version: cfg.PROMPT_VERSION, action_taken: action,
  needs_human: reasons.length > 0, needs_human_reasons: reasons, ticket_id: td ? td.ticket_id : '', reply_draft: pc.reply_draft || '',
  processed_at: new Date().toISOString(), error: errors.join(' | '), notes, json_valid_first_try: fin.json_valid_first_try,
  tokens_est: tokensIn + tokensOut, cost_usd_est: Math.round(cost * 1e6) / 1e6 });
return [{ json: row }];

// What the caller gets back: the audit row plus a few debugging fields.
const row = $('Build Audit Row').first().json;
const fin = $('Finalize Classification').first().json;
const lookup = $('Resolve Order').first().json;
const pc = $('Postcheck Reply').first().json;
let td = null; try { td = $('Ticket Decision').first().json; } catch (e) { td = null; }
return [{ json: Object.assign({}, row, { needs_human: row.needs_human === 'TRUE', order_found: row.order_found === 'TRUE', json_valid_first_try: row.json_valid_first_try === 'TRUE',
  llm_order_id: fin.llm_order_id, order_match: lookup.match_method, repair_method: fin.repair_method, ticket_action: td ? td.action : 'none',
  tools_called: pc.tools_called || [], postcheck_failures: pc.critical || [] }) }];
